package com.gkowdeck.gameday.firetv;
import org.junit.Test;
import static org.junit.Assert.*;
public class FollowTest {
 @Test public void queuePriorityAndFifo(){FollowQueue q=new FollowQueue();q.push(new FollowQueue.Event(0,EventEffects.POWER_PLAY,"EDM",100),100);q.push(new FollowQueue.Event(1,EventEffects.GOAL,"TOR",101),101);q.push(new FollowQueue.Event(2,EventEffects.GOAL,"BOS",102),102);assertEquals(1,q.pop(103).game);assertEquals(2,q.pop(103).game);assertEquals(0,q.pop(103).game);assertNull(q.pop(103));}
 @Test public void expiryAndCancel(){FollowQueue q=new FollowQueue();q.push(new FollowQueue.Event(0,0,"EDM",100),100);q.push(new FollowQueue.Event(1,0,"TOR",100),100);q.removeGame(0);assertEquals(1,q.size());assertNull(q.pop(20101));}
 @Test public void boundedQueuePrioritizesGoals(){FollowQueue q=new FollowQueue();for(int i=0;i<8;i++)assertTrue(q.push(new FollowQueue.Event(0,EventEffects.POWER_PLAY,"EDM",100),100));assertFalse(q.push(new FollowQueue.Event(0,EventEffects.POWER_PLAY,"EDM",100),100));assertTrue(q.push(new FollowQueue.Event(3,0,"TOR",100),100));assertEquals(8,q.size());assertEquals(3,q.pop(100).game);}
 @Test public void configRoundTripAndDisplayOnly()throws Exception {FollowConfig c=new FollowConfig();FollowConfig.Game g=new FollowConfig.Game();g.id=2026020001L;g.away="EDM";g.home="TOR";g.display=false;g.sound=true;g.delay=45;g.mask=63;g.ddp=true;c.games.add(g);c.validate();FollowConfig copy=FollowConfig.parse(c.json());assertEquals(1,copy.games.size());assertTrue(copy.games.get(0).sound);assertFalse(copy.games.get(0).display);assertEquals(45,copy.games.get(0).delay);assertEquals(63,copy.games.get(0).mask);assertFalse(c.json().contains("armed"));}
 @Test public void targetValidation()throws Exception {FollowConfig c=new FollowConfig();FollowConfig.Game g=new FollowConfig.Game();g.id=2026020001L;c.games.add(g);g.outputs=3;c.targets[0]="192.168.1.71";c.targets[1]="192.168.1.71";try{c.validate();fail();}catch(Exception expected){}c.targets[1]="192.168.1.72";c.validate();c.targets[1]="8.8.8.8";try{c.validate();fail();}catch(Exception expected){}}
 @Test public void sanitizeDuplicateAndLimits()throws Exception {String item="{\"id\":2026020001,\"targets\":255,\"mask\":255,\"delay\":999}";FollowConfig c=FollowConfig.parse("{\"games\":["+item+","+item+"]}");assertEquals(1,c.games.size());assertEquals(3,c.games.get(0).outputs);assertEquals(127,c.games.get(0).mask);assertEquals(90,c.games.get(0).delay);}
 @Test public void independentTargetQueues(){FollowQueue a=new FollowQueue(),b=new FollowQueue();FollowQueue.Event event=new FollowQueue.Event(0,0,"EDM",100);a.push(event,100);b.push(event,100);a.clear();assertNull(a.pop(100));assertNotNull(b.pop(100));}
}
